import React from 'react';
import {AbsoluteFill, Sequence} from 'remotion';
import {SUBS} from './subs';
import {fitSize, textW} from './textfit';

/**
 * Subtitles: white #FFF Noto Sans SC 700 at 44px, centered at x=640, CSS top 637 (ink at y644–684), black outline 4px (a 16+8+4-direction text-shadow ring, which avoids the sharp spikes of -webkit-text-stroke).
 * No background box (the fog sets them off). Cut in and out on single frames. Entries are generated by scripts/tts_build.py from the voiceover's word boundaries (Chinese ≤16 characters / English ≤48 characters per chunk).
 */
export const SUB_STYLE = {fontSize: 44, weight: 700, top: 637, color: '#FFFFFF', stroke: 4, strokeColor: '#000000'};
export const SUB_MAX_W = 1160; // safe area x60–1220. Anything wider shrinks automatically to a 34px fallback (Chinese ≤16 or English ≤48 characters normally fit anyway)
const ring = (r: number, k: number, col: string) => Array.from({length: k}, (_, i) => {
  const a = (i / k) * Math.PI * 2;
  return `${(Math.cos(a) * r).toFixed(2)}px ${(Math.sin(a) * r).toFixed(2)}px 0 ${col}`;
});
export const strokeShadow = (w = SUB_STYLE.stroke, col = SUB_STYLE.strokeColor) => [...ring(w, 16, col), ...ring(w * 0.6, 8, col), ...ring(w * 0.3, 4, col)].join(', ');

export const SubtitleLine: React.FC<{text: string; top?: number; left?: number; color?: string; stroke?: number}> = ({text, top = SUB_STYLE.top, left = 640, color = SUB_STYLE.color, stroke = SUB_STYLE.stroke}) => {
  // A subtitle chunk is one line by default (the subtitle band is only 53px high). If it is too wide, the font shrinks to 34px first.
  // If even 34px does not fit (an English chunk over 70 characters), it wraps onto two lines and grows upward. That pushes into the content area, but it is more readable than being cut off at both ends.
  // This is a fallback, not the design. tts_build.py already flags such chunks with ⚠ against the safe-area width. The correct fix is to split the chunk with another |.
  const size = fitSize(text, SUB_MAX_W, SUB_STYLE.fontSize, 34);
  const lh = 1.2;
  const font: React.CSSProperties = {fontFamily: `'Noto Sans SC', 'PingFang SC', sans-serif`, fontWeight: SUB_STYLE.weight, fontSize: size, lineHeight: lh, color, textShadow: strokeShadow(stroke)};
  if (textW(text, size) <= SUB_MAX_W) {
    return <div style={{position: 'absolute', left, top, transform: 'translateX(-50%)', whiteSpace: 'nowrap', ...font}}>{text}</div>;
  }
  // Wrap fallback: a box two lines tall, with its bottom edge at the single-line position (flex column, bottom-aligned).
  // This way, whether Chromium wraps to one line or two (the width estimate and real layout can differ by a few percent), the last line lands in the subtitle band.
  // Even if a third line appears, it can only overflow upward into the content area, never into the progress bar.
  const lineH = Math.round(size * lh);
  return (
    <div style={{position: 'absolute', left, top: top - lineH, transform: 'translateX(-50%)', width: SUB_MAX_W, height: lineH * 2, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', textAlign: 'center', whiteSpace: 'normal', ...font}}>
      <div>{text}</div>
    </div>
  );
};
export const Subtitles: React.FC = () => (
  <AbsoluteFill style={{pointerEvents: 'none'}}>
    {SUBS.map((s, k) => (
      <Sequence key={k} from={s.from - 1} durationInFrames={Math.max(1, s.to - s.from + 1)}>
        <SubtitleLine text={s.text} />
      </Sequence>
    ))}
  </AbsoluteFill>
);
